 : '' }}</small><small class="text-secondary">{{ $detail->cantidad }} × S/ {{ number_format((float)$detail->precio_unitario,2) }} · Descuento S/ {{ number_format((float)$detail->descuento,2) }}</small></div><strong>S/ {{ number_format((float)$detail->subtotal, 2) }}</strong></div>@empty<div class="text-secondary py-4">Todavía no agregaste procedimientos.</div>@endforelse</div></div></div>
            <div class="col-lg-4"><div class="card border-0 shadow-sm mb-3"><div class="card-body"><h2 class="h5">Decisión del paciente</h2><p class="small text-secondary">Registra si el paciente acepta o rechaza este presupuesto. Esta acción no registra un pago.</p>@if($version?->estado === 'ENVIADO')@can('planes.responder')<form method="POST" action="{{ route('odontologia.planes.respond', $plan) }}" data-response-form data-patient="{{ $plan->paciente?->nombres }} {{ $plan->paciente?->apellidos }}" data-version="{{ $version->numero_version }}" data-total="{{ number_format((float)$version->total, 2) }}">@csrf @method('PATCH')<input type="hidden" name="id_version" value="{{ $version->id_version }}"><input type="hidden" name="decision" value="" data-decision-field><textarea class="form-control mb-2 @error('observacion') is-invalid @enderror" name="observacion" placeholder="Observación opcional para la aceptación; obligatoria si rechazas.">{{ old('observacion') }}</textarea>@error('observacion')<div class="invalid-feedback d-block">{{ $message }}</div>@enderror<div class="d-flex gap-2"><button type="submit" name="decision" value="ACEPTADO" class="btn btn-success flex-fill">Registrar aceptación</button><button type="submit" name="decision" value="RECHAZADO" class="btn btn-outline-danger flex-fill">Registrar rechazo</button></div></form>@else<p class="text-secondary mb-0">Sin permiso para responder esta versión.</p>@endcan @elseif($version)<p class="mb-0">Estado: <strong>{{ $version->estado }}</strong>@if($version->respondido_at)<small class="d-block text-secondary">Registrado el {{ $version->respondido_at->format('d/m/Y H:i') }}@if($version->usuarioRespuesta) por {{ $version->usuarioRespuesta->nombre_completo }}@endif</small>@endif</p>@if($version->observacion_respuesta)<p class="small text-secondary mb-0">Observación: {{ $version->observacion_respuesta }}</p>@endif @endif</div></div><div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Resumen clínico</h2><div class="fs-4">{{ $clinical['percent'] }}%</div><small class="text-secondary">{{ $clinical['done'] }} de {{ $clinical['total'] }} procedimientos realizados</small><a href="{{ route('odontologia.planes.show', [$plan, 'tab' => 'sessions']) }}" class="btn btn-outline-primary w-100 mt-3">Ver sesiones y avance</a></div></div></div></div>
    @endif
