<script>
document.querySelectorAll('[data-response-form]').forEach(form => { const field=form.querySelector('[data-decision-field]'); const buttons=[...form.querySelectorAll('button[name="decision"]')]; buttons.forEach(button=>button.addEventListener('click',()=>field.value=button.value)); form.addEventListener('submit',event=>{const decision=field.value||event.submitter?.value;if(!decision){event.preventDefault();return;}field.value=decision;const label=decision==='RECHAZADO'?'rechaza':'acepta';if(!confirm(`¿Confirmas que ${form.dataset.patient.trim()||'el paciente'} ${label} la Revisión ${form.dataset.version} · S/${form.dataset.total}?`)){event.preventDefault();return;}buttons.forEach(button=>{button.removeAttribute('name');button.disabled=true;});}); });
document.querySelectorAll('[data-cancel-session]').forEach(form => form.addEventListener('submit', event => { const reason = prompt('Indica el motivo de anulación:'); if (!reason || !reason.trim()) { event.preventDefault(); return; } form.querySelector('[name="motivo"]').value = reason.trim(); }));
</script>
